package com.styleshop.order.service;
import com.styleshop.order.model.*;import com.styleshop.order.repository.*;import jakarta.transaction.Transactional;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Service public class ShoppingService {private final CartRepository carts;private final OrderRepository orders;private final RestClient products;public ShoppingService(CartRepository c,OrderRepository o,RestClient r){carts=c;orders=o;products=r;}
 @Transactional public CartDto add(String user,Long productId){ProductDto p=products.get().uri("/api/products/{id}",productId).retrieve().body(ProductDto.class);CartItem i=carts.findByUsernameAndProductId(user,productId).orElseGet(()->{CartItem x=new CartItem();x.setUsername(user);x.setProductId(productId);x.setName(p.name());x.setPrice(p.price());x.setImageUrl(p.imageUrl());return x;});if(i.getId()!=null)i.setQuantity(i.getQuantity()+1);carts.save(i);return cart(user);}
 public CartDto cart(String user){List<CartItem> list=carts.findByUsernameOrderById(user);List<CartLine> lines=list.stream().map(CartLine::of).toList();BigDecimal total=lines.stream().map(CartLine::subtotal).reduce(BigDecimal.ZERO,BigDecimal::add);int qty=list.stream().mapToInt(CartItem::getQuantity).sum();return new CartDto(lines,total,total,BigDecimal.ZERO,BigDecimal.ZERO,total,qty);}
 @Transactional public CartDto change(String user,Long id,int delta){CartItem i=carts.findById(id).filter(x->x.getUsername().equals(user)).orElseThrow();i.setQuantity(i.getQuantity()+delta);if(i.getQuantity()<=0)carts.delete(i);else carts.save(i);return cart(user);}
 @Transactional public void remove(String user,Long id){carts.findById(id).filter(x->x.getUsername().equals(user)).ifPresent(carts::delete);}@Transactional public void clear(String user){carts.deleteByUsername(user);}
 @Transactional public OrderDto checkout(String user){List<CartItem> list=carts.findByUsernameOrderById(user);if(list.isEmpty())throw new IllegalStateException("購物車是空的");ShopOrder o=new ShopOrder();o.setUsername(user);o.setCreatedAt(LocalDateTime.now());o.setStatus("CREATED");BigDecimal total=BigDecimal.ZERO;for(CartItem c:list){OrderItem i=new OrderItem();i.setOrder(o);i.setProductId(c.getProductId());i.setProductName(c.getName());i.setPrice(c.getPrice());i.setImageUrl(c.getImageUrl());i.setQuantity(c.getQuantity());o.getItems().add(i);total=total.add(c.getPrice().multiply(BigDecimal.valueOf(c.getQuantity())));}o.setTotalAmount(total);orders.save(o);carts.deleteByUsername(user);return OrderDto.of(o);}
 @Transactional public OrderDto orderNow(String user,Long productId){ProductDto p=products.get().uri("/api/products/{id}",productId).retrieve().body(ProductDto.class);if(p==null)throw new NoSuchElementException("商品不存在");ShopOrder o=new ShopOrder();o.setUsername(user);o.setCreatedAt(LocalDateTime.now());o.setStatus("CREATED");OrderItem i=new OrderItem();i.setOrder(o);i.setProductId(p.id());i.setProductName(p.name());i.setPrice(p.price());i.setImageUrl(p.imageUrl());i.setQuantity(1);o.getItems().add(i);o.setTotalAmount(p.price());orders.save(o);return OrderDto.of(o);}
 public List<OrderDto> list(String user){return orders.findByUsernameOrderByCreatedAtDesc(user).stream().map(OrderDto::of).toList();}public List<OrderDto> listAll(){return orders.findAllByOrderByCreatedAtDesc().stream().map(OrderDto::of).toList();}public OrderDto one(String user,Long id){return OrderDto.of(orders.findByIdAndUsername(id,user).orElseThrow());}@Transactional public OrderDto cancel(String user,Long id){ShopOrder o=orders.findByIdAndUsername(id,user).orElseThrow();o.setStatus("CANCELLED");return OrderDto.of(orders.save(o));}
 public record ProductDto(Long id,String name,BigDecimal price,String description,String imageUrl,String productUrl,Long categoryId,String categoryName){}public record CartLine(Long id,Long productId,String name,BigDecimal price,String imageUrl,int quantity,BigDecimal subtotal){static CartLine of(CartItem i){return new CartLine(i.getId(),i.getProductId(),i.getName(),i.getPrice(),i.getImageUrl(),i.getQuantity(),i.getPrice().multiply(BigDecimal.valueOf(i.getQuantity())));}}public record CartDto(List<CartLine> items,BigDecimal total,BigDecimal subtotal,BigDecimal shippingFee,BigDecimal discountAmount,BigDecimal finalAmount,int totalQuantity){}public record OrderLine(Long id,Long productId,String productName,BigDecimal price,String imageUrl,int quantity,BigDecimal subtotal){static OrderLine of(OrderItem i){return new OrderLine(i.getId(),i.getProductId(),i.getProductName(),i.getPrice(),i.getImageUrl(),i.getQuantity(),i.getPrice().multiply(BigDecimal.valueOf(i.getQuantity())));}}public record OrderDto(Long id,String username,LocalDateTime createdAt,BigDecimal totalAmount,String status,List<OrderLine> items){static OrderDto of(ShopOrder o){return new OrderDto(o.getId(),o.getUsername(),o.getCreatedAt(),o.getTotalAmount(),o.getStatus(),o.getItems().stream().map(OrderLine::of).toList());}}}
